     1	import { useMemo } from "react";
     2	import { useRadarrQueue, useRadarrHistory } from "@/hooks/use-radarr";
     3	import { useSonarrQueue, useSonarrHistory } from "@/hooks/use-sonarr";
     4	import { getRadarrPoster } from "@/services/radarr-api";
     5	import { getSonarrPoster } from "@/services/sonarr-api";
     6	import { getJSON, setJSON } from "@/store/storage";
     7	import { STORAGE_KEYS } from "@/lib/constants";
     8	
     9	export interface TorrentPosterEntry {
    10	  posterUrl: string | null;
    11	  title: string;
    12	  mediaType: "movie" | "tv";
    13	  routeId: number; // movie.id or series.id, for navigation
    14	}
    15	
    16	// Sticky hash→entry mapping. The *arr queue only lists in-flight downloads, so
    17	// without persistence the Downloads widget cover would vanish the moment
    18	// Radarr/Sonarr imports a finished file (#88). The cache is populated
    19	// additively from the live queue, the *arr history (covers recent completions
    20	// from previous sessions), and any prior persisted snapshot — so seeding
    21	// torrents keep their posters across app launches.
    22	const stickyPosterCache = new Map<string, TorrentPosterEntry>();
    23	let cacheHydrated = false;
    24	
    25	function hydrateCacheOnce(): void {
    26	  if (cacheHydrated) return;
    27	  cacheHydrated = true;
    28	  const stored = getJSON<Record<string, TorrentPosterEntry>>(
    29	    STORAGE_KEYS.torrentPosterCache,
    30	  );
    31	  if (!stored) return;
    32	  for (const [hash, entry] of Object.entries(stored)) {
    33	    if (entry && typeof entry === "object") {
    34	      stickyPosterCache.set(hash, entry);
    35	    }
    36	  }
    37	}
    38	
    39	function persistCache(): void {
    40	  setJSON(
    41	    STORAGE_KEYS.torrentPosterCache,
    42	    Object.fromEntries(stickyPosterCache),
    43	  );
    44	}
    45	
    46	/**
    47	 * Strict torrent → media mapping. qBittorrent's torrent hash equals the *arr
    48	 * `downloadId` for any torrent grabbed via Radarr or Sonarr — so we can look
    49	 * up posters deterministically without parsing torrent names.
    50	 *
    51	 * Returns a map keyed by lowercased hash. Returns an empty map if neither
    52	 * *arr is enabled (graceful degradation: tiles fall back to the icon).
    53	 */
    54	export function useTorrentPosterMap(): Map<string, TorrentPosterEntry> {
    55	  const { data: radarrQueue } = useRadarrQueue();
    56	  const { data: sonarrQueue } = useSonarrQueue();
    57	  const { data: radarrHistory } = useRadarrHistory();
    58	  const { data: sonarrHistory } = useSonarrHistory();
    59	
    60	  return useMemo(() => {
    61	    hydrateCacheOnce();
    62	    const sizeBefore = stickyPosterCache.size;
    63	
    64	    for (const item of radarrQueue?.records ?? []) {
    65	      if (!item.downloadId || !item.movie) continue;
    66	      stickyPosterCache.set(item.downloadId.toLowerCase(), {
    67	        posterUrl: getRadarrPoster(item.movie.images),
    68	        title: item.movie.title,
    69	        mediaType: "movie",
    70	        routeId: item.movie.id,
    71	      });
    72	    }
    73	
    74	    for (const item of sonarrQueue?.records ?? []) {
    75	      if (!item.downloadId || !item.series) continue;
    76	      stickyPosterCache.set(item.downloadId.toLowerCase(), {
    77	        posterUrl: getSonarrPoster(item.series.images),
    78	        title: item.series.title,
    79	        mediaType: "tv",
    80	        routeId: item.series.id,
    81	      });
    82	    }
    83	
    84	    // History backfills the cold-start gap: torrents that finished in a
    85	    // previous session won't appear in the queue, but their grab/import event
    86	    // is still in history with the same `downloadId` (== torrent hash). Only
    87	    // records that already include the embedded movie/series get used; older
    88	    // events without the embed are skipped.
    89	    for (const record of radarrHistory?.records ?? []) {
    90	      if (!record.downloadId || !record.movie) continue;
    91	      const key = record.downloadId.toLowerCase();
    92	      if (stickyPosterCache.has(key)) continue;
    93	      stickyPosterCache.set(key, {
    94	        posterUrl: getRadarrPoster(record.movie.images),
    95	        title: record.movie.title,
    96	        mediaType: "movie",
    97	        routeId: record.movie.id,
    98	      });
    99	    }
   100	
   101	    for (const record of sonarrHistory?.records ?? []) {
   102	      if (!record.downloadId || !record.series) continue;
   103	      const key = record.downloadId.toLowerCase();
   104	      if (stickyPosterCache.has(key)) continue;
   105	      stickyPosterCache.set(key, {
   106	        posterUrl: getSonarrPoster(record.series.images),
   107	        title: record.series.title,
   108	        mediaType: "tv",
   109	        routeId: record.series.id,
   110	      });
   111	    }
   112	
   113	    if (stickyPosterCache.size > sizeBefore) persistCache();
   114	
   115	    return new Map(stickyPosterCache);
   116	  }, [radarrQueue, sonarrQueue, radarrHistory, sonarrHistory]);
   117	}
