     1	import AsyncStorage from "@react-native-async-storage/async-storage";
     2	import * as SecureStore from "expo-secure-store";
     3	
     4	// In-memory cache — populated once during initStorage(), then all reads are sync
     5	const cache: Record<string, string> = {};
     6	
     7	export async function initStorage(): Promise<void> {
     8	  const keys = await AsyncStorage.getAllKeys();
     9	  const entries = await AsyncStorage.multiGet(keys as string[]);
    10	  for (const [key, value] of entries) {
    11	    if (key && value !== null) cache[key] = value;
    12	  }
    13	}
    14	
    15	// --- Sync helpers (read from cache, write-through to AsyncStorage) ---
    16	
    17	export function getString(key: string): string | undefined {
    18	  return cache[key];
    19	}
    20	
    21	export function setString(key: string, value: string): void {
    22	  cache[key] = value;
    23	  AsyncStorage.setItem(key, value);
    24	}
    25	
    26	export function getBoolean(key: string): boolean {
    27	  return cache[key] === "true";
    28	}
    29	
    30	export function setBoolean(key: string, value: boolean): void {
    31	  cache[key] = String(value);
    32	  AsyncStorage.setItem(key, String(value));
    33	}
    34	
    35	export function deleteKey(key: string): void {
    36	  delete cache[key];
    37	  AsyncStorage.removeItem(key);
    38	}
    39	
    40	// --- SecureStore helpers (API keys, passwords) ---
    41	
    42	export async function getSecret(key: string): Promise<string | null> {
    43	  return SecureStore.getItemAsync(key);
    44	}
    45	
    46	export async function setSecret(
    47	  key: string,
    48	  value: string,
    49	  options?: SecureStore.SecureStoreOptions,
    50	): Promise<void> {
    51	  await SecureStore.setItemAsync(key, value, options);
    52	}
    53	
    54	export async function deleteSecret(key: string): Promise<void> {
    55	  await SecureStore.deleteItemAsync(key);
    56	}
    57	
    58	// --- JSON helpers ---
    59	
    60	export function getJSON<T>(key: string): T | undefined {
    61	  const raw = cache[key];
    62	  if (!raw) return undefined;
    63	  try {
    64	    return JSON.parse(raw) as T;
    65	  } catch {
    66	    return undefined;
    67	  }
    68	}
    69	
    70	export function setJSON(key: string, value: unknown): void {
    71	  const json = JSON.stringify(value);
    72	  cache[key] = json;
    73	  AsyncStorage.setItem(key, json);
    74	}
    75	
    76	// Atomic multi-key write. Use when two keys must land together or not at all
    77	// (e.g. `dashboards` + `activeDashboardId`): `multiSet` batches them into one
    78	// AsyncStorage operation, so a crash/kill can't persist one without the other
    79	// and leave the pair desynced. Each value is pre-serialized by the caller.
    80	export function setMany(entries: [string, string][]): void {
    81	  for (const [key, value] of entries) cache[key] = value;
    82	  AsyncStorage.multiSet(entries);
    83	}
